const fs = require('fs');
const path = require('path');

const BASE_DIR = '/home/user/n8n-files/projects';

const input = $input.first().json;
const projectId = String(input.query?.project_id || '').replace(/[^a-zA-Z0-9_-]/g, '');
const subPath = String(input.query?.path || '').replace(/\.\./g, '').replace(/[^a-zA-Z0-9/_.-]/g, '_');

if (!projectId || !subPath) {
  return [{ json: [] }];
}

const targetDir = path.join(BASE_DIR, projectId, subPath);

try {
  if (!fs.existsSync(targetDir)) {
    return [{ json: { files: [] } }];
  }

  const entries = fs.readdirSync(targetDir, { withFileTypes: true });
  const files = entries
    .filter(e => e.isFile())
    .map(e => {
      const stat = fs.statSync(path.join(targetDir, e.name));
      return {
        name: e.name,
        size: stat.size,
        modified: stat.mtime.toISOString()
      };
    })
    .sort((a, b) => new Date(b.modified) - new Date(a.modified));

  return [{ json: files }];
} catch (err) {
  return [{ json: [] }];
}
